"""Independent NumPy/SciPy/librosa numerical references (optional developer tool).

Inputs are rounded to float32 before being saved and before reference calculation.
LPC uses the autocorrelation/Yule-Walker estimator, not librosa's Burg estimator:
https://docs.scipy.org/doc/scipy/reference/generated/scipy.linalg.solve_toeplitz.html
PCEN uses librosa with an explicitly matched initial smoothing state:
https://librosa.org/doc/0.11.0/generated/librosa.pcen.html
DTW and Viterbi use librosa.sequence, with the latter's uniform initial-state
log prior removed to match dasp-rs's unweighted initial state scores.
"""
from pathlib import Path

import librosa
import numpy as np
import scipy
from scipy.linalg import solve_toeplitz
from scipy.signal import correlate, lfilter

assert np.__version__ == "2.3.5"
assert scipy.__version__ == "1.18.1"
assert librosa.__version__ == "0.11.0"

lines = [
    "# numpy=2.3.5 scipy=1.18.1 librosa=0.11.0; generated by generate_core_reference.py",
    "# Stored inputs are exact float32 values; reference arithmetic is float64.",
    "name,row,col,real,imag",
]


def save(name, value):
    a = np.atleast_2d(value)
    assert np.isfinite(a).all(), name
    for (row, col), v in np.ndenumerate(a):
        lines.append(f"{name},{row},{col},{float(np.real(v)):.17e},{float(np.imag(v)):.17e}")


rng = np.random.default_rng(20261101)
t = np.arange(127, dtype=np.float64) / 8000
signals = {
    "noise": rng.uniform(-0.8, 0.8, 127),
    "voiced": 0.5 * np.sin(2 * np.pi * 220 * t) + 0.2 * np.sin(2 * np.pi * 443 * t),
    "ar": lfilter([1.0], [1.0, -0.75, 0.2], rng.uniform(-0.3, 0.3, 127)),
    "impulse": np.eye(1, 127, 41)[0],
}
for name, values in signals.items():
    for tag, scale in [("normal", 1.0), ("quiet", 1e-20), ("loud", 1e15)]:
        y = (values * scale).astype(np.float32).astype(np.float64)
        key = f"lpc_{name}_{tag}"
        save(key + "_input", y)
        correlation = correlate(y, y, mode="full", method="direct")[len(y) - 1:]
        save(key + "_autocorrelation", correlation[:13])
        for order in [1, 4, 12]:
            coefficients = solve_toeplitz(correlation[:order], -correlation[1:order + 1])
            save(key + f"_order{order}", np.r_[1.0, coefficients])

amplitude = np.array([[0.0, 1e-6, 0.2, 2.0, 10.0], [1e-4, 0.03, 0.5, 1.0, 100.0]], dtype=np.float32).astype(np.float64)
save("amplitude_input", amplitude)
save("amplitude_db", librosa.amplitude_to_db(amplitude, ref=0.5, amin=1e-5, top_db=72.0))
power = (amplitude * amplitude).astype(np.float32).astype(np.float64)
save("power_input", power)
save("power_db", librosa.power_to_db(power, ref=0.25, amin=1e-10, top_db=72.0))
db = np.array([[-80, -20, 0, 6, 40]], dtype=np.float32).astype(np.float64)
save("db_input", db)
save("db_amplitude", librosa.db_to_amplitude(db, ref=0.5))
save("db_power", librosa.db_to_power(db, ref=0.25))

frequencies = np.array([0, 10, 20, 50, 100, 500, 1000, 2000, 5000, 10000, 20000], dtype=np.float32).astype(np.float64)
save("weighting_input", frequencies)
for kind in "ABCD":
    with np.errstate(divide="ignore"):
        db_weights = librosa.frequency_weighting(frequencies, kind=kind, min_db=None)
    # dasp-rs returns linear amplitude gains and discards gains below min_db.
    save("weighting_" + kind, np.where(db_weights < -80.0, 0.0, 10.0 ** (db_weights / 20.0)))

envelope = np.array([[0, 0, 1, 8, 2, 0.1, 0, 0, 4, 1], [3, 3, 3, 3, 0, 0, 0, 0, 1, 9]], dtype=np.float32)
for tag, scale in [("normal", 1.0), ("quiet", 1e-12), ("loud", 1e12)]:
    s = (envelope * np.float32(scale)).astype(np.float64)
    save("pcen_" + tag + "_input", s)
    for sr, hop, gain, bias in [(8000, 64, 0.98, 2.0), (22050, 256, 0.5, 0.0)]:
        gain = float(np.float32(gain))
        t_frames = 0.4 * sr / hop
        b = 2 / (np.sqrt(1 + 4 * t_frames * t_frames) + 1)
        # librosa evaluates log(0) for silent bins with zero bias, then exp(-inf).
        with np.errstate(divide="ignore"):
            result = librosa.pcen(s, sr=sr, hop_length=hop, gain=gain, bias=bias,
                                  power=0.5, eps=1e-6, b=b, zi=(1 - b) * s[:, :1])
        save(f"pcen_{tag}_{sr}", result)

mu_input = np.array([-1, -0.8, -0.1, -1e-8, 0, 1e-8, 0.1, 0.8, 1], dtype=np.float32).astype(np.float64)
save("mu_input", mu_input)
for mu in [1.0, 255.0]:
    save(f"mu_compress_{int(mu)}", librosa.mu_compress(mu_input, mu=mu, quantize=False))
    save(f"mu_expand_{int(mu)}", librosa.mu_expand(mu_input, mu=mu, quantize=False))

for case, (n, m) in enumerate([(5, 7), (12, 9), (1, 4)]):
    x = rng.uniform(-1, 1, (3, n)).astype(np.float32).astype(np.float64)
    y = rng.uniform(-1, 1, (3, m)).astype(np.float32).astype(np.float64)
    save(f"dtw_{case}_x", x)
    save(f"dtw_{case}_y", y)
    for metric in ["euclidean", "cityblock", "cosine"]:
        costs, path = librosa.sequence.dtw(X=x, Y=y, metric=metric)
        save(f"dtw_{case}_{metric}_cost", costs[-1, -1])
        save(f"dtw_{case}_{metric}_path", path[::-1])

for case, (states, frames) in enumerate([(2, 8), (4, 19), (7, 100)]):
    probabilities = rng.uniform(0.05, 0.95, (states, frames)).astype(np.float32).astype(np.float64)
    transition = rng.uniform(0.05, 1, (states, states))
    transition /= transition.sum(axis=1, keepdims=True)
    transition = transition.astype(np.float32).astype(np.float64)
    path, logp = librosa.sequence.viterbi(probabilities, transition, return_logp=True)
    save(f"viterbi_{case}_emissions", probabilities)
    save(f"viterbi_{case}_transition", transition)
    save(f"viterbi_{case}_path", path)
    save(f"viterbi_{case}_score", np.asarray(logp).item() + np.log(states))

Path(__file__).with_name("core_reference.csv").write_text("\n".join(lines) + "\n")
print(f"Generated {len(lines) - 3} core reference values")
